runs.program:
res = single_object(scene_id="living_room", label="sofa")
if not res.ok:
    submit("unknown", evidence=["single_object(sofa) failed: " + str(res.error.code)])

sofa = res.value
sofa_id = sofa["object_id"]

attr = get_attributes(scene_id="living_room", object_id=sofa_id, attrs=["color"])
if not attr.ok:
    submit("unknown", evidence=["get_attributes failed: " + str(attr.error.code)])

val = attr.value
color = None
if isinstance(val, dict):
    color = val.get("color")
    if color is None and "attributes" in val and isinstance(val["attributes"], dict):
        color = val["attributes"].get("color")
elif isinstance(val, str):
    color = val

if not color:
    submit("unknown", evidence=["color attribute missing for sofa id=" + sofa_id])

submit(str(color), target_ids=[sofa_id], evidence=["get_attributes(object_id=%s, attrs=['color']) -> %s" % (sofa_id, color)])
